"""Apply the locally verified V3.2 delta, refusing every unexpected preimage.

This one-use CI transport is removed after readable source is tested and committed.
No shell payload or external download is evaluated; the payload is JSON text edits.
"""
from pathlib import Path
import base64, hashlib, json, lzma
ROOT = Path(__file__).resolve().parents[1]
PAYLOAD = """"""
EXPECTED = "ef5d34fa411e0cf6b137267140a38eb73d43f3749c35ba3ec481dfa39a1c1950"
records = json.loads(lzma.decompress(base64.b64decode(PAYLOAD)))
prepared = []
seen = set()
for record in records:
    name = record['path']
    path = ROOT / name
    if (name in seen or Path(name).is_absolute() or '..' in Path(name).parts
            or not (name.startswith(('src/', 'tests/', 'docs/')) or name in ('README.md', 'package.json', 'tools/build.mjs'))):
        raise SystemExit('Refusing unexpected path: ' + name)
    seen.add(name)
    if path.is_symlink():
        raise SystemExit('Refusing symlink: ' + name)
    old = path.read_bytes() if path.exists() else None
    digest = hashlib.sha256(old).hexdigest() if old is not None else None
    if digest != record['before']:
        raise SystemExit('Source changed; reconcile before publishing: ' + name)
    text = old.decode('utf-8') if old is not None else ''
    for start, end, replacement in reversed(record['edits']):
        if not (0 <= start <= end <= len(text)):
            raise SystemExit('Invalid edit range: ' + name)
        text = text[:start] + replacement + text[end:]
    result = text.encode('utf-8')
    if hashlib.sha256(result).hexdigest() != record['after']:
        raise SystemExit('Postimage mismatch: ' + name)
    prepared.append((path, result))
# Validate ALL preimages and postimages before writing any source file.
for path, result in prepared:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(result)
(ROOT / '.v32-expected.sha256').write_text(EXPECTED + '  index.html\n')
print('Applied', len(prepared), 'verified source changes. Rebuild and tests are still required.')
